        errors.append(f'line {n}: duplicate reference {ref}')
    refs.add(ref)
    if any(item not in allowed_basis for item in basis.split('+')):
        errors.append(f'line {n}: invalid basis')
    if not explanation.strip():
        errors.append(f'line {n}: empty explanation')
print(f'{len(rows)} rows; {len(refs)} unique references')
print('\n'.join(errors) if errors else 'TSV format checks passed')
